# Manually verify the movies directed by Quentin Tarantino
content = movie_note['content']
lines = content.split('\n')

# Check if "Django Unchained" appears and is followed by Quentin Tarantino director
if "Django Unchained" in content:
    django_index = content.find("Django Unchained")
    if django_index != -1:
        # Check if it's followed by a director line
        director_line = content[django_index + len("Django Unchained"):].strip()
        if " - director: Quentin Tarantino" in director_line:
            quentin_tarantino_movies = ["Django Unchained", "Pulp Fiction"]
        else:
            quentin_tarantino_movies = ["Pulp Fiction"]
    else:
        quentin_tarantino_movies = ["Pulp Fiction"]
else:
    quentin_tarantino_movies = ["Pulp Fiction"]

# Check if "Pulp Fiction" appears and is followed by Quentin Tarantino director
if "Pulp Fiction" in content:
    pulp_index = content.find("Pulp Fiction")
    if pulp_index != -1:
        director_line = content[pulp_index + len("Pulp Fiction"):].strip()
        if " - director: Quentin Tarantino" in director_line:
            quentin_tarantino_movies = ["Django Unchained", "Pulp Fiction"]
        else:
            quentin_tarantino_movies = ["Django Unchained"]
    else:
        quentin_tarantino_movies = ["Django Unchained"]
else:
    quentin_tarantino_movies = ["Django Unchained"]

print(quentin_tarantino_movies)
